-- CMD #2189 — Load every India pincode with its centroid into public.geo_pincode.
--
-- Source: GeoNames postal-code export IN.zip (https://download.geonames.org/export/zip/IN.zip),
-- CC BY 4.0, downloaded 2026-09-23. Columns used: postal code, admin1 (state),
-- admin2 (district), latitude, longitude. 155,570 source rows -> 19,238 distinct pincodes.
-- A pincode's centroid is the AVERAGE lat/lng of every post office GeoNames files under it.
--
-- geo_pincode is the ground truth that corrects a coarse geocoder result, so the whole point
-- is coverage: it held 23 rows and India has ~19,300 pincodes.
--
-- Names are normalised to the official LGD list (geo_state / geo_district) through the SAME
-- alias table the registration Location step reads (geo_place_alias -> geo_state_pick /
-- geo_district_pick), so district lookups keep matching. GeoNames ships older or alternate
-- spellings (Allahabad, Gurgaon, Cuddapah, Khorda, Pondicherry); each one is added as an
-- alias rather than silently rewritten, which fixes registration lookups too.
--
-- Existing rows are NOT deleted: GeoNames wins wherever it has a centroid, and a pincode
-- GeoNames does not list keeps its existing 'seed' / 'geocoder' row untouched.
--
-- Idempotent: staging is rebuilt, aliases upsert, geo_pincode upserts on its primary key.
-- Touches nothing in geo_reverse or geo_reverse_cache.

begin;

set local statement_timeout = '900s';

-- ---------------------------------------------------------------- LGD name aliases
-- State spellings GeoNames uses that geo_state_pick() cannot reach on its own
-- ('&' is stripped by geo_key, and LGD's own name carries a leading "The").
select public.geo_key(v.src), s.lgd_code, null, 'GeoNames state spelling (CMD #2189)'
  from (values
    ('Andaman & Nicobar Islands','Andaman and Nicobar Islands'),
    ('Jammu & Kashmir','Jammu and Kashmir'),
    ('Dadra and Nagar Haveli and Daman and Diu','The Dadra and Nagar Haveli and Daman and Diu')
       ) as v(src, lgd)
  join public.geo_state s on s.name = v.lgd
    on conflict (alias_key, state_lgd) do nothing;

-- District spellings GeoNames uses, mapped to the LGD district of the same place.
-- Renames (Allahabad -> Prayagraj, Osmanabad -> Dharashiv, Karimganj -> Sribhumi),
-- transliterations (Khorda -> Khordha, Darjiling -> Darjeeling) and splits whose HQ is
-- unambiguous (Jaintia Hills -> West Jaintia Hills, East Sikkim -> Gangtok).
-- Kept as a table because it is BOTH the alias source and this load's own lookup: a key
-- that already exists as a STATE alias (district_lgd null, e.g. 'pondicherry') must not be
-- overwritten -- geo_state_pick() reads exactly those rows -- but the load still needs it.
create table if not exists public._c2189_name_map (
  state_name text, src_district text, lgd_district text,
  state_lgd int, district_lgd int
);
delete from public._c2189_name_map;

select v.state_name, v.src, v.lgd_name, d.state_lgd, d.lgd_code
  from (values
    ('Andaman and Nicobar Islands','Nicobar','Nicobars'),
    ('Andaman and Nicobar Islands','South Andaman','South Andamans'),
    ('Andhra Pradesh','Ananthapur','Ananthapuramu'),
    ('Andhra Pradesh','Cuddapah','Y.S.R. Kadapa'),
    ('Andhra Pradesh','Nellore','Sri Potti Sriramulu Nellore'),
    ('Assam','Karimganj','Sribhumi'),
    ('Assam','North Cachar Hills','Dima Hasao'),
    ('Assam','Sibsagar','Sivasagar'),
    ('Bihar','East Champaran','Purbi Champaran'),
    ('Bihar','Kaimur','Kaimur (Bhabua)'),
    ('Bihar','West Champaran','Pashchim Champaran'),
    ('The Dadra and Nagar Haveli and Daman and Diu','Dadra & Nagar Haveli','Dadra And Nagar Haveli'),
    ('Delhi','Central Delhi','Central'),
    ('Delhi','East Delhi','East'),
    ('Delhi','North Delhi','North'),
    ('Delhi','North West Delhi','North West'),
    ('Delhi','South Delhi','South'),
    ('Delhi','South West Delhi','South West'),
    ('Delhi','West Delhi','West'),
    ('Gujarat','The Dangs','Dangs'),
    ('Haryana','Gurgaon','Gurugram'),
    ('Himachal Pradesh','Lahul & Spiti','Lahaul And Spiti'),
    ('Jammu and Kashmir','Ananthnag','Anantnag'),
    ('Jammu and Kashmir','Bandipur','Bandipora'),
    ('Jammu and Kashmir','Rajauri','Rajouri'),
    ('Jharkhand','East Singhbhum','East Singhbum'),
    ('Jharkhand','Giridh','Giridih'),
    ('Jharkhand','Hazaribag','Hazaribagh'),
    ('Jharkhand','Palamau','Palamu'),
    ('Jharkhand','Sahibganj','Sahebganj'),
    ('Jharkhand','Seraikela-kharsawan','Saraikela Kharsawan'),
    ('Karnataka','Bagalkot','Bagalkote'),
    ('Karnataka','Bangalore Rural','Bengaluru Rural'),
    ('Karnataka','Bengaluru','Bengaluru Urban'),
    ('Karnataka','Chamrajnagar','Chamarajanagar'),
    ('Karnataka','Chikkaballapur','Chikkaballapura'),
    ('Karnataka','Davangere','Davanagere'),
    ('Karnataka','Ramanagar','Bengaluru South'),
    ('Kerala','Kasargod','Kasaragod'),
    ('Lakshadweep','Lakshadweep','Lakshadweep District'),
    ('Madhya Pradesh','East Nimar','Khandwa (East Nimar)'),
    ('Madhya Pradesh','Hoshangabad','Narmadapuram'),
    ('Madhya Pradesh','Narsinghpur','Narsimhapur'),
    ('Madhya Pradesh','Sainkheda','Narsimhapur'),
    ('Madhya Pradesh','West Nimar','Khargone (West Nimar)'),
    ('Maharashtra','Ahmed Nagar','Ahilyanagar'),
    ('Maharashtra','Osmanabad','Dharashiv'),
    ('Meghalaya','Jaintia Hills','West Jaintia Hills'),
    ('Mizoram','Mammit','Mamit'),
    ('Mizoram','Saiha','Siaha'),
    ('Nagaland','Zunhebotto','Zunheboto'),
    ('Odisha','Angul','Anugola'),
    ('Odisha','Baleswar','Baleshwar'),
    ('Odisha','Bargarh','Baragada'),
    ('Odisha','Cuttack','Kataka'),
    ('Odisha','Debagarh','Debagada'),
    ('Odisha','Jajapur','Jajpur'),
    ('Odisha','Kandhamal','Kandhamala'),
    ('Odisha','Kendrapara','Kendrapada'),
    ('Odisha','Keonjhargarh','Kendujhar'),
    ('Odisha','Khorda','Khordha'),
    ('Odisha','Nabarangapur','Nabarangpur'),
    ('Odisha','Nayagarh','Nayagada'),
    ('Odisha','Sonapur','Subarnapur'),
    ('Odisha','Sundergarh','Sundaragada'),
    ('Puducherry','Pondicherry','Puducherry'),
    ('Punjab','Firozpur','Ferozepur'),
    ('Punjab','Mohali','S.A.S Nagar'),
    ('Punjab','Muktsar','Sri Muktsar Sahib'),
    ('Punjab','Nawanshahr','Shahid Bhagat Singh Nagar'),
    ('Punjab','Ropar','Rupnagar'),
    ('Rajasthan','Jalor','Jalore'),
    ('Rajasthan','Jhujhunu','Jhunjhunu'),
    ('Sikkim','East Sikkim','Gangtok'),
    ('Sikkim','North Sikkim','Mangan'),
    ('Sikkim','South Sikkim','Namchi'),
    ('Sikkim','West Sikkim','Gyalshing'),
    ('Tamil Nadu','Kanchipuram','Kancheepuram'),
    ('Tamil Nadu','Kanyakumari','Kanniyakumari'),
    ('Tamil Nadu','Nilgiris','The Nilgiris'),
    ('Tamil Nadu','Tiruvallur','Thiruvallur'),
    ('Tamil Nadu','Tiruvarur','Thiruvarur'),
    ('Tamil Nadu','Tuticorin','Thoothukkudi'),
    ('Tamil Nadu','Villupuram','Viluppuram'),
    ('Telangana','K.V.Rangareddy','Ranga Reddy'),
    ('Tripura','Gomti','Gomati'),
    ('Uttar Pradesh','Allahabad','Prayagraj'),
    ('Uttar Pradesh','Bagpat','Baghpat'),
    ('Uttar Pradesh','Faizabad','Ayodhya'),
    ('Uttar Pradesh','Jyotiba Phule Nagar','Amroha'),
    ('Uttar Pradesh','Maharajganj','Mahrajganj'),
    ('Uttar Pradesh','Sant Ravidas Nagar','Bhadohi'),
    ('West Bengal','Darjiling','Darjeeling'),
    ('West Bengal','East Midnapore','Purba Medinipur'),
    ('West Bengal','North Dinajpur','Uttar Dinajpur'),
    ('West Bengal','South Dinajpur','Dakshin Dinajpur'),
    ('West Bengal','West Midnapore','Paschim Medinipur'),
    ('Ladakh','Leh','Leh Ladakh')
       ) as v(state_name, src, lgd_name)
  join public.geo_state s on s.name = v.state_name
  join public.geo_district d on d.state_lgd = s.lgd_code and d.name = v.lgd_name;

select public.geo_key(m.src_district), m.state_lgd, m.district_lgd,
       'GeoNames district spelling (CMD #2189)'
  from public._c2189_name_map m
    on conflict (alias_key, state_lgd) do nothing;

-- ---------------------------------------------------------------- staging
create table if not exists public._c2189_geonames_raw (
  pincode  text primary key,
  district text,
  state    text,
  lat      double precision not null,
  lng      double precision not null
);

delete from public._c2189_geonames_raw;


-- GeoNames disambiguates same-named districts inline ("Bilaspur(CGH)", "Kaimur (Bhabua)").
-- geo_key() would keep those letters, so drop the bracket before the LGD lookup.
update public._c2189_geonames_raw
   set district = btrim(regexp_replace(district, '\s*\(.*\)\s*$', ''))
 where district like '%(%';

-- ---------------------------------------------------------------- resolve against LGD
-- Three passes, widest last. The STATE always comes from the matched district's own
-- state_lgd, never from the GeoNames label: GeoNames still files Leh and Kargil under
-- "Jammu & Kashmir" and LGD moved them to Ladakh.
drop table if exists public._c2189_resolved;
create table public._c2189_resolved as
with base as (
  select g.pincode, g.lat, g.lng, g.district as raw_district, g.state as raw_state,
         (public.geo_state_pick(g.state)).lgd_code as st_lgd,
         public.geo_key(g.district) as dkey
    from public._c2189_geonames_raw g
), hit as (
  select b.*,
         coalesce(
           -- 1. the district, inside the GeoNames state
           (select d.lgd_code from public.geo_district d
             where d.state_lgd = b.st_lgd and public.geo_key(d.name) = b.dkey
             order by d.lgd_code limit 1),
           -- 2. this load's curated name map, inside the GeoNames state
           (select m.district_lgd from public._c2189_name_map m
             where m.state_lgd = b.st_lgd and public.geo_key(m.src_district) = b.dkey
             limit 1),
           -- 3. an alias inside the GeoNames state
           (select a.district_lgd from public.geo_place_alias a
             where a.state_lgd = b.st_lgd and a.alias_key = b.dkey and a.district_lgd is not null
             limit 1),
           -- 4. no state hint: only a UNIQUE answer counts
           (select max(x.lgd_code) from (
              select d.lgd_code from public.geo_district d where public.geo_key(d.name) = b.dkey
              union
              select a.district_lgd from public.geo_place_alias a
               where a.alias_key = b.dkey and a.district_lgd is not null
            ) x having count(*) = 1)
         ) as d_lgd
    from base b
)
select h.pincode,
       coalesce(d.name, h.raw_district) as district,
       coalesce(s2.name, s1.name, h.raw_state) as state,
       h.lat, h.lng,
       (d.lgd_code is not null) as lgd_matched
  from hit h
  left join public.geo_district d on d.lgd_code = h.d_lgd
  left join public.geo_state s2 on s2.lgd_code = d.state_lgd
  left join public.geo_state s1 on s1.lgd_code = h.st_lgd;

do $$
declare v_m int; v_u int;
begin
  select count(*) filter (where lgd_matched), count(*) filter (where not lgd_matched)
    into v_m, v_u from public._c2189_resolved;
  raise notice 'c2189: LGD district matched %, kept verbatim %', v_m, v_u;
end $$;

-- ---------------------------------------------------------------- upsert
select r.pincode, r.district, r.state, r.lat, r.lng, 'geonames', now()
  from public._c2189_resolved r
 where r.pincode ~ '^[1-9][0-9]{5}$'
    on conflict (pincode) do update
       set district   = excluded.district,
           state      = excluded.state,
           lat        = excluded.lat,
           lng        = excluded.lng,
           source     = excluded.source,
           updated_at = now();

drop table if exists public._c2189_resolved;
drop table if exists public._c2189_geonames_raw;
drop table if exists public._c2189_name_map;

commit;
